// SPDX-License-Identifier: MPL-2.0
//
// e2ee.js — peer-side group-key crypto for the browser client.
//
// This is the other half of ADR-0016. The server coordinates (public keys,
// epochs, opaque blobs); everything secret happens here, in the client, using
// WebCrypto only — no dependencies, no bundler, no server-held key.
//
// The values it produces are pinned by client/web/tests/fixtures/e2ee-vectors.json,
// which was generated by the Elixir implementation and is re-derived here on
// every test run. If the two ever disagree, `deno task test` fails.
//
//   Elixir (Burble.Media.E2EE)          Browser (this module)
//   --------------------------          ---------------------
//   generate_keypair/0                  generateKeypair()
//   pairwise_key/6                      pairwiseKey()
//   seal_group_key/6                    sealGroupKey()
//   open_group_key/6                    openGroupKey()
//   derive_frame_key/3                  deriveFrameKey()
//   encode_sealed/1                     encodeSealed()
//
// ## What is NOT here
//
// The RTCRtpScriptTransform wiring (Insertable Streams / Encoded Transform)
// needs a browser and a dedicated worker; it is deliberately not written yet,
// so nothing in this file should be described as "encrypting calls today".
// What is here is the crypto an encoded transform would call, tested against
// the server's own output.
//
// ## Wire formats
//
//   public key   32 bytes, raw X25519
//   private key  CryptoKey (non-extractable where the platform allows)
//   sealed key  iv(12) || tag(16) || ciphertext(32)  = 60 bytes
//   frame       iv(12) || tag(16) || ciphertext(n)
//
// Labels are domain separators. Changing any of them, or the AAD layout, is a
// wire break and needs an ADR revision.

const LABEL_PAIRWISE = "burble-e2ee-pairwise-v1";
const LABEL_GROUP = "burble-e2ee-group-v1";
const LABEL_FRAME = "burble-e2ee-frame-v1";

const KEY_BYTES = 32;
const IV_BYTES = 12;
const TAG_BYTES = 16;
const SEALED_BYTES = IV_BYTES + TAG_BYTES + KEY_BYTES;

const encoder = new TextEncoder();
const enc = s => encoder.encode(s);

// PKCS#8 wrapper for a raw X25519 private key (OID 1.3.101.110, key as an inner
// OCTET STRING). WebCrypto will not import a raw X25519 private key — this is
// the one awkward detail of the whole protocol, and it is why the vectors exist.
const PKCS8_PREFIX = Uint8Array.from([
  0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x6e, 0x04, 0x22, 0x04, 0x20
]);

/** Whether this browser implements the primitives the protocol needs. */
export function isSupported() {
  return (
    typeof crypto !== "undefined" &&
    typeof crypto.subtle !== "undefined" &&
    typeof crypto.subtle.generateKey === "function"
  );
}

// ── Encoding helpers ────────────────────────────────────────────────────────

export function toBase64(bytes) {
  let binary = "";
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary);
}

export function fromBase64(text) {
  const binary = atob(text);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

export function toHex(bytes) {
  return Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
}

export function fromHex(hex) {
  if (hex.length % 2 !== 0) throw new RangeError("hex string must have even length");
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

const concat = (...parts) => {
  const total = parts.reduce((n, p) => n + p.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const p of parts) {
    out.set(p, offset);
    offset += p.length;
  }
  return out;
};

const equal = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);

// ── Keys ────────────────────────────────────────────────────────────────────

/**
 * Generate an ephemeral X25519 keypair. One per room, per epoch.
 *
 * @returns {Promise<{publicKey: Uint8Array, privateKey: CryptoKey}>}
 *   `publicKey` is the raw 32 bytes you publish; the private key never leaves
 *   this process and is not extractable.
 */
export async function generateKeypair() {
  const pair = await crypto.subtle.generateKey({ name: "X25519" }, false, ["deriveBits"]);

  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", pair.publicKey));
  if (raw.length !== KEY_BYTES) throw new Error(`unexpected public key length ${raw.length}`);

  return { publicKey: raw, privateKey: pair.privateKey };
}

/**
 * Import a raw 32-byte X25519 private key (tests, or a persisted key).
 *
 * `extractable` defaults to false; only tests should set it, since exporting a
 * private key is exactly what the protocol is designed to avoid.
 */
export async function importPrivateKey(raw, { extractable = false } = {}) {
  if (raw.length !== KEY_BYTES) throw new RangeError("X25519 private key must be 32 bytes");
  return crypto.subtle.importKey(
    "pkcs8",
    concat(PKCS8_PREFIX, raw),
    { name: "X25519" },
    extractable,
    ["deriveBits"]
  );
}

/** Export a private key as raw bytes. Only works for keys imported as extractable. */
export async function exportPrivateKey(privateKey) {
  const pkcs8 = new Uint8Array(await crypto.subtle.exportKey("pkcs8", privateKey));
  return pkcs8.subarray(pkcs8.length - KEY_BYTES);
}

const importPublicKey = raw => {
  if (raw.length !== KEY_BYTES) throw new RangeError("X25519 public key must be 32 bytes");
  return crypto.subtle.importKey("raw", raw, { name: "X25519" }, false, []);
};

// ── Pairwise agreement ──────────────────────────────────────────────────────

/**
 * Derive the key shared by exactly two peers in a room and epoch.
 *
 * salt = SHA-256("pairwise|" || room || "|" || epoch)
 * info = LABEL_PAIRWISE || "|" || join(sorted([a, b]), "|")
 *
 * Sorting makes the result identical on both sides without either peer needing
 * to know who is "first"; the server knows neither private key.
 *
 * @returns {Promise<Uint8Array>} 32-byte key
 */
export async function pairwiseKey(myPrivateKey, theirPublicKey, roomId, epoch, myPeerId, theirPeerId) {
  const shared = await crypto.subtle.deriveBits(
    { name: "X25519", public: await importPublicKey(theirPublicKey) },
    myPrivateKey,
    256
  );

  const salt = new Uint8Array(
    await crypto.subtle.digest("SHA-256", enc(`pairwise|${roomId}|${epoch}`))
  );

  const info = enc(`${LABEL_PAIRWISE}|${[myPeerId, theirPeerId].sort().join("|")}`);

  const hkdf = await crypto.subtle.importKey("raw", shared, "HKDF", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt, info }, hkdf, 256);

  return new Uint8Array(bits);
}

// ── Group-key sealing ───────────────────────────────────────────────────────

/** AAD binds a sealed blob to room, epoch, sender and recipient. */
export function sealAad(roomId, epoch, fromId, toId) {
  return enc(`${LABEL_GROUP}|${roomId}|${epoch}|${fromId}|${toId}`);
}

/** Generate a random 32-byte room key. Leader only. */
export function randomGroupKey() {
  return crypto.getRandomValues(new Uint8Array(KEY_BYTES));
}

/**
 * Seal the room key for one peer under the pairwise key.
 *
 * @returns {Promise<Uint8Array>} 60-byte wire form: iv || tag || ciphertext
 */
export async function sealGroupKey(groupKey, pairwise, roomId, epoch, fromId, toId) {
  if (groupKey.length !== KEY_BYTES) throw new RangeError("group key must be 32 bytes");
  if (pairwise.length !== KEY_BYTES) throw new RangeError("pairwise key must be 32 bytes");

  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES));
  const key = await crypto.subtle.importKey("raw", pairwise, "AES-GCM", false, ["encrypt"]);

  const sealed = new Uint8Array(
    await crypto.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: sealAad(roomId, epoch, fromId, toId), tagLength: 128 },
      key,
      groupKey
    )
  );

  // WebCrypto appends the tag; the wire form puts it before the ciphertext.
  const ciphertext = sealed.subarray(0, sealed.length - TAG_BYTES);
  const tag = sealed.subarray(sealed.length - TAG_BYTES);

  return concat(iv, tag, ciphertext);
}

/**
 * Open a sealed room key addressed to this peer.
 *
 * Throws on a wrong key, wrong room, wrong epoch, swapped direction or a
 * tampered blob — the AAD check covers all four.
 *
 * @returns {Promise<Uint8Array>} 32-byte room key
 */
export async function openGroupKey(wire, pairwise, roomId, epoch, fromId, toId) {
  if (wire.length !== SEALED_BYTES) {
    throw new RangeError(`sealed key must be ${SEALED_BYTES} bytes, got ${wire.length}`);
  }
  if (pairwise.length !== KEY_BYTES) throw new RangeError("pairwise key must be 32 bytes");

  const iv = wire.subarray(0, IV_BYTES);
  const tag = wire.subarray(IV_BYTES, IV_BYTES + TAG_BYTES);
  const ciphertext = wire.subarray(IV_BYTES + TAG_BYTES);

  const key = await crypto.subtle.importKey("raw", pairwise, "AES-GCM", false, ["decrypt"]);

  const plaintext = new Uint8Array(
    await crypto.subtle.decrypt(
      { name: "AES-GCM", iv, additionalData: sealAad(roomId, epoch, fromId, toId), tagLength: 128 },
      key,
      concat(ciphertext, tag)
    )
  );

  if (plaintext.length !== KEY_BYTES) throw new Error("sealed key did not open to 32 bytes");
  return plaintext;
}

/** Encode/decode the wire form explicitly (the channel carries base64 text). */
export const encodeSealed = wire => {
  if (wire.length !== SEALED_BYTES) throw new RangeError("sealed key must be 60 bytes");
  return wire;
};

export const decodeSealed = text => {
  const bytes = typeof text === "string" ? fromBase64(text) : text;
  if (bytes.length !== SEALED_BYTES) throw new RangeError("sealed key must be 60 bytes");
  return bytes;
};

// ── Frames ──────────────────────────────────────────────────────────────────

/**
 * Derive the per-frame key — the shape pinned by the Elixir implementation.
 *
 * salt = SHA-256("frame|" || epoch)
 * info = LABEL_FRAME || "|" || counter
 *
 * Kept arity-for-arity with `Burble.Media.E2EE.derive_frame_key/3` so the
 * vectors can pin it. See `deriveSenderFrameKey` for the variant the frame
 * layer actually uses.
 *
 * @returns {Promise<Uint8Array>} 32 raw key bytes
 */
export async function deriveFrameKey(groupKey, epoch, counter) {
  return deriveFrameBits(groupKey, epoch, `${counter}`);
}

async function deriveFrameBits(groupKey, epoch, infoSuffix) {
  if (groupKey.length !== KEY_BYTES) throw new RangeError("group key must be 32 bytes");

  const salt = new Uint8Array(await crypto.subtle.digest("SHA-256", enc(`frame|${epoch}`)));
  const info = enc(`${LABEL_FRAME}|${infoSuffix}`);

  const hkdf = await crypto.subtle.importKey("raw", groupKey, "HKDF", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt, info }, hkdf, 256);

  return new Uint8Array(bits);
}

/** Import raw frame-key bytes as an AES-GCM key. One per frame. */
export function frameCipher(rawKey) {
  if (rawKey.length !== KEY_BYTES) throw new RangeError("frame key must be 32 bytes");
  return crypto.subtle.importKey("raw", rawKey, "AES-GCM", false, ["encrypt", "decrypt"]);
}

/**
 * Derive the per-frame key *for a named sender*.
 *
 * The group key alone authenticates the room, not the speaker: every member
 * holds it, so any member could forge frames that appear to come from any
 * other. Mixing the sender id into the derivation (and into the AAD) makes a
 * frame attributable — a peer can still forge its *own* frames, which it is
 * entitled to do, but not anyone else's.
 *
 * info = LABEL_FRAME || "|sender|" || senderId || "|" || counter
 *
 * @returns {Promise<Uint8Array>} 32 raw key bytes
 */
export async function deriveSenderFrameKey(groupKey, epoch, senderId, counter) {
  if (typeof senderId !== "string" || senderId.length === 0) {
    throw new TypeError("senderId must be a non-empty string");
  }

  return deriveFrameBits(groupKey, epoch, `sender|${senderId}|${counter}`);
}

/** AAD for a frame: room, epoch, sender and counter, in that order. */
export function frameAad(roomId, epoch, senderId, counter) {
  return enc(`frame-aad|${roomId}|${epoch}|${senderId}|${counter}`);
}

/**
 * Encrypt one media frame. This is what an encoded transform would call.
 *
 * @returns {Promise<Uint8Array>} iv || tag || ciphertext
 */
export async function encryptFrame(frameKey, plaintext, roomId, epoch, senderId, counter) {
  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES));

  const sealed = new Uint8Array(
    await crypto.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: frameAad(roomId, epoch, senderId, counter), tagLength: 128 },
      await frameCipher(frameKey),
      plaintext
    )
  );

  // Same layout as a sealed key: iv || tag || ciphertext.
  const ciphertext = sealed.subarray(0, sealed.length - TAG_BYTES);
  const tag = sealed.subarray(sealed.length - TAG_BYTES);
  return concat(iv, tag, ciphertext);
}

/** Decrypt one media frame. Throws if the AAD does not match. */
export async function decryptFrame(frameKey, wire, roomId, epoch, senderId, counter) {
  if (wire.length <= IV_BYTES + TAG_BYTES) throw new RangeError("frame too short");

  const iv = wire.subarray(0, IV_BYTES);
  const tag = wire.subarray(IV_BYTES, IV_BYTES + TAG_BYTES);
  const ciphertext = wire.subarray(IV_BYTES + TAG_BYTES);

  const plaintext = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv, additionalData: frameAad(roomId, epoch, senderId, counter), tagLength: 128 },
    await frameCipher(frameKey),
    concat(ciphertext, tag)
  );

  return new Uint8Array(plaintext);
}

// ── Replay window ───────────────────────────────────────────────────────────

/**
 * A sliding replay window for received frame counters.
 *
 * Decryption already rejects a replayed *frame* (the counter is in the AAD),
 * but only within the window of keys you still hold. This tracks which
 * counters have been accepted so a duplicate is refused outright rather than
 * costing a decrypt.
 */
export class ReplayWindow {
  #seen = new Set();
  #size;
  #highest = -1;

  constructor(size = 256) {
    if (!Number.isInteger(size) || size < 1) throw new RangeError("window size must be a positive integer");
    this.#size = size;
  }

  /**
   * True if `counter` would be accepted, without recording it.
   *
   * The frame layer needs this: it must refuse a replay *before* paying for a
   * decrypt, but it must not burn the counter if the decrypt then fails —
   * otherwise a corrupted frame would take its counter down with it and a
   * genuine retransmission of the same frame would be dropped as a replay.
   */
  wouldAccept(counter) {
    if (!Number.isInteger(counter) || counter < 0) throw new RangeError("counter must be a non-negative integer");
    if (this.#seen.has(counter)) return false;
    if (this.#highest - counter >= this.#size) return false;
    return true;
  }

  /** True if `counter` is new; records it. False if it is a replay or too old. */
  accept(counter) {
    if (!this.wouldAccept(counter)) return false;

    this.#seen.add(counter);
    if (counter > this.#highest) {
      this.#highest = counter;
      const floor = counter - this.#size + 1;
      for (const c of this.#seen) if (c < floor) this.#seen.delete(c);
    }

    return true;
  }

  get highest() {
    return this.#highest;
  }

  get size() {
    return this.#seen.size;
  }
}

// ── Epoch handling ──────────────────────────────────────────────────────────

/**
 * Track the room's epoch and invalidate everything when it moves.
 *
 * A membership change bumps the epoch, which means: new keypair, new pairwise
 * keys, new room key. Anything derived from the old epoch is dropped rather
 * than cached, because the peer that left still holds it.
 */
export class KeyEpoch {
  #epoch = 0;
  #keypair = null;
  #roomKey = null;
  #frameKeys = new Map();

  constructor(roomId) {
    this.roomId = roomId;
  }

  get epoch() {
    return this.#epoch;
  }

  /** Adopt an epoch from the server; drops all key material if it advanced. */
  advanceTo(epoch) {
    if (!Number.isInteger(epoch) || epoch < 0) throw new RangeError("epoch must be a non-negative integer");
    if (epoch === this.#epoch) return false;
    if (epoch < this.#epoch) return false; // stale message; ignore rather than rewind

    this.#epoch = epoch;
    this.#roomKey = null;
    this.#frameKeys.clear();

    return true;
  }

  async rotate() {
    this.#keypair = await generateKeypair();
    this.#roomKey = null;
    this.#frameKeys.clear();
    return this.#keypair.publicKey;
  }

  setRoomKey(key) {
    if (key.length !== KEY_BYTES) throw new RangeError("room key must be 32 bytes");
    this.#roomKey = key;
    this.#frameKeys.clear();
  }

  hasRoomKey() {
    return this.#roomKey !== null;
  }

  async frameKey(senderId, counter) {
    if (!this.#roomKey) throw new Error("no room key for this epoch");
    return deriveSenderFrameKey(this.#roomKey, this.#epoch, senderId, counter);
  }

  /** Drop everything. Call on leave. */
  clear() {
    this.#keypair = null;
    this.#roomKey = null;
    this.#frameKeys.clear();
  }
}


// ── Frames on the wire ──────────────────────────────────────────────────────
//
// A frame is `header || iv(12) || tag(16) || ciphertext(n)`.
//
// The header exists because the counter is an input to *both* the key
// derivation and the AAD, so a receiver cannot decrypt a frame without it.
// Sending it out of band would mean trusting the signalling path to deliver a
// per-frame value in order, which under reordering is exactly the thing the
// replay window is supposed to tolerate. Nine bytes per frame is the honest
// price: version(1) || epoch(4, BE) || counter(4, BE).
//
// The epoch is carried *and* checked: it is already inside the AAD, so a frame
// from another epoch fails to decrypt anyway. Checking it first turns an
// expected event (a membership change) into a clean rejection instead of a
// crypto error in a log.

const FRAME_VERSION = 1;
const FRAME_HEADER_BYTES = 1 + 4 + 4;
const UINT32_MAX = 0xffffffff;

/** Build a frame header. Both fields are uint32 by construction. */
export function encodeFrameHeader(epoch, counter) {
  if (!Number.isInteger(epoch) || epoch < 0 || epoch > UINT32_MAX) {
    throw new RangeError("epoch must be a uint32");
  }
  if (!Number.isInteger(counter) || counter < 0 || counter > UINT32_MAX) {
    throw new RangeError("counter must be a uint32");
  }

  const header = new Uint8Array(FRAME_HEADER_BYTES);
  header[0] = FRAME_VERSION;
  const view = new DataView(header.buffer);
  view.setUint32(1, epoch);
  view.setUint32(5, counter);
  return header;
}

/** Parse a frame header. Throws rather than guessing on anything unrecognised. */
export function decodeFrameHeader(bytes) {
  if (!(bytes instanceof Uint8Array) || bytes.length < FRAME_HEADER_BYTES) {
    throw new RangeError("frame is shorter than its header");
  }
  if (bytes[0] !== FRAME_VERSION) {
    throw new Error(`unsupported frame version ${bytes[0]}`);
  }

  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return {
    version: bytes[0],
    epoch: view.getUint32(1),
    counter: view.getUint32(5),
    body: bytes.subarray(FRAME_HEADER_BYTES)
  };
}

/**
 * Encrypt one frame, header included.
 *
 * @returns {Promise<Uint8Array>} header || iv || tag || ciphertext
 */
export async function sealFrame(groupKey, plaintext, roomId, epoch, senderId, counter) {
  const key = await deriveSenderFrameKey(groupKey, epoch, senderId, counter);
  const body = await encryptFrame(key, plaintext, roomId, epoch, senderId, counter);
  return concat(encodeFrameHeader(epoch, counter), body);
}

/**
 * Encrypt a frame with a key the caller already derived (the `FrameCryptor`
 * path, which caches nothing but avoids derivations the caller tracks itself).
 */
export async function sealFrameWithKey(frameKey, plaintext, roomId, epoch, senderId, counter) {
  const body = await encryptFrame(frameKey, plaintext, roomId, epoch, senderId, counter);
  return concat(encodeFrameHeader(epoch, counter), body);
}

/**
 * Cryptor for one direction of one peer connection.
 *
 * Holds the send counter and the per-sender replay windows. One instance per
 * peer connection: in a mesh call each peer has its own connection and its own
 * `remotePeerId`, which is what binds a received frame to a speaker.
 */
export class FrameCryptor {
  #epochs;
  #roomId;
  #localId;
  #counter = 0;
  #window = null;
  #remoteId;
  #onError;

  constructor({ epochs, roomId, localId, remoteId, onError = null, windowSize = 256 }) {
    if (!epochs || typeof epochs.frameKey !== "function") throw new TypeError("FrameCryptor needs a KeyEpoch");
    if (typeof roomId !== "string" || roomId.length === 0) throw new TypeError("roomId is required");
    if (typeof localId !== "string" || localId.length === 0) throw new TypeError("localId is required");
    if (typeof remoteId !== "string" || remoteId.length === 0) {
      throw new TypeError("remoteId is required: a frame key is bound to its sender");
    }

    this.#epochs = epochs;
    this.#roomId = roomId;
    this.#localId = localId;
    this.#remoteId = remoteId;
    this.#onError = onError;
    this.#window = new ReplayWindow(windowSize);
    this.windowSize = windowSize;
  }

  get epoch() {
    return this.#epochs.epoch;
  }

  get sentCount() {
    return this.#counter;
  }

  /** Drop the replay window — call when the epoch moves. */
  reset() {
    this.#counter = 0;
    this.#window = new ReplayWindow(this.windowSize);
  }

  /** Seal one outgoing frame. Counter starts at 0 for each epoch. */
  async seal(plaintext) {
    if (this.#counter > UINT32_MAX) throw new RangeError("frame counter exhausted for this epoch");
    const epoch = this.#epochs.epoch;
    const counter = this.#counter++;
    const key = await this.#epochs.frameKey(this.#localId, counter);
    return sealFrameWithKey(key, plaintext, this.#roomId, epoch, this.#localId, counter);
  }

  /**
   * Open one incoming frame from `remoteId` (defaults to the address this
   * cryptor was built for).
   *
   * Rejects: wrong epoch, replay or too-old counter, wrong sender (the AAD
   * binds it), tampered ciphertext.
   */
  async open(wire, remoteId = this.#remoteId) {
    const { epoch, counter, body } = decodeFrameHeader(wire);

    if (epoch !== this.#epochs.epoch) {
      throw new Error(`frame is from epoch ${epoch}, current is ${this.#epochs.epoch}`);
    }
    if (!this.#window.wouldAccept(counter)) {
      throw new Error(`frame counter ${counter} is a replay or outside the window`);
    }

    const key = await this.#epochs.frameKey(remoteId, counter);
    const plaintext = await decryptFrame(key, body, this.#roomId, epoch, remoteId, counter);

    // Only now is the counter spent: a frame that failed to decrypt leaves the
    // window untouched, so a genuine retransmission is still accepted.
    this.#window.accept(counter);
    return plaintext;
  }
}

// ── Encoded Transform plumbing ──────────────────────────────────────────────

/**
 * What this browser can do. Reported rather than assumed: the two APIs are
 * mutually exclusive in practice (Chrome shipped `createEncodedStreams`, then
 * moved to `RTCRtpScriptTransform`, which needs a dedicated worker).
 */
export function describeTransformSupport() {
  const senderProto = typeof RTCRtpSender !== "undefined" ? RTCRtpSender.prototype : null;
  const receiverProto = typeof RTCRtpReceiver !== "undefined" ? RTCRtpReceiver.prototype : null;

  return {
    createEncodedStreams:
      !!senderProto && typeof senderProto.createEncodedStreams === "function" &&
      !!receiverProto && typeof receiverProto.createEncodedStreams === "function",
    scriptTransform: typeof RTCRtpScriptTransform !== "undefined"
  };
}

/** A transform that seals outgoing frames in place. Drops a frame it cannot seal. */
export function senderTransform(cryptor, { onError = null } = {}) {
  return new TransformStream({
    async transform(frame, controller) {
      try {
        frame.data = await cryptor.seal(new Uint8Array(frame.data));
        controller.enqueue(frame);
      } catch (e) {
        // Fail closed. Dropping one frame is a glitch in the call; forwarding
        // it in the clear is a disclosure, and no exception is worth that.
        if (onError) onError(e);
      }
    }
  });
}

/** A transform that opens incoming frames in place. Drops a frame it cannot open. */
export function receiverTransform(cryptor, { onError = null } = {}) {
  return new TransformStream({
    async transform(frame, controller) {
      try {
        frame.data = await cryptor.open(new Uint8Array(frame.data));
        controller.enqueue(frame);
      } catch (e) {
        if (onError) onError(e);
      }
    }
  });
}

/**
 * Attach encryption to every sender and decryption to every receiver on a
 * peer connection.
 *
 * @returns {{ok: boolean, results: Array<{direction: string, ok: boolean, reason?: string}>}}
 *          `ok: false` means media is NOT protected; the caller must treat that
 *          as fatal for an `:e2ee` room rather than continuing quietly.
 */
export function attachFrameCrypto(pc, { cryptor, role = "both", onError = null } = {}) {
  if (!pc || typeof pc.getSenders !== "function") throw new TypeError("attachFrameCrypto needs an RTCPeerConnection");
  if (!(cryptor instanceof FrameCryptor)) throw new TypeError("attachFrameCrypto needs a FrameCryptor");

  const results = [];

  if (role === "sender" || role === "both") {
    for (const sender of pc.getSenders()) {
      results.push({ direction: "send", ...pipeSender(sender, cryptor, onError) });
    }
  }

  if (role === "receiver" || role === "both") {
    for (const receiver of pc.getReceivers()) {
      results.push({ direction: "receive", ...pipeReceiver(receiver, cryptor, onError) });
    }
  }

  if (results.length === 0) {
    return { ok: false, results: [{ direction: "none", ok: false, reason: "no transceivers" }] };
  }

  return { ok: results.every(r => r.ok), results };
}

function streamsOf(endpoint) {
  if (typeof endpoint.createEncodedStreams !== "function") return null;

  const streams = endpoint.createEncodedStreams();
  if (!streams) return null;

  // Chrome has shipped both spellings; accept either rather than pinning one.
  const readable = streams.readable ?? streams.readStream;
  const writable = streams.writable ?? streams.writeStream;
  if (!readable || !writable) return null;

  return { readable, writable };
}

function pipeSender(sender, cryptor, onError) {
  const streams = streamsOf(sender);
  if (!streams) return { ok: false, reason: "encoded-transform-unavailable" };

  streams.readable
    .pipeThrough(senderTransform(cryptor, { onError }))
    .pipeTo(streams.writable)
    .catch(err => onError?.(err));

  return { ok: true };
}

function pipeReceiver(receiver, cryptor, onError) {
  const streams = streamsOf(receiver);
  if (!streams) return { ok: false, reason: "encoded-transform-unavailable" };

  streams.readable
    .pipeThrough(receiverTransform(cryptor, { onError }))
    .pipeTo(streams.writable)
    .catch(err => onError?.(err));

  return { ok: true };
}

export const CONSTANTS = {
  FRAME_VERSION,
  FRAME_HEADER_BYTES,
  KEY_BYTES,
  IV_BYTES,
  TAG_BYTES,
  SEALED_BYTES,
  LABEL_PAIRWISE,
  LABEL_GROUP,
  LABEL_FRAME,
  equal,
  concat
};
